  "titulo": "Polanco vs Santa Fe: comparativa para vivir o invertir en CDMX",
  "ciudad": "Ciudad de México",
  "categoria": "Comparativa",
  "fecha": "2025-06-15",
  "modificado": "2026-10-25",
